#include <iostream>
#include <string>

int main() {
    std::string name = "Nathanael";
    int age = 20;
    int x = 4, y = 7;

    std::cout << name << ", " << age << " år\n";
    std::cout << "Summa: " << x + y << "\n";
    if (age >= 18) {
        std::cout << "Myndig\n";
    } else {
        std::cout << "Under 18\n";
    }
    return 0;
}
